// === Tab: Particle ===
class Particle {
	constructor(x, y, size) {
		this.pos = createVector(x, y)
		this.size = size
	}

	update() {
		const p = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))))
		const d = this.pos.dist(p)
		const w = p5.Vector.sub(this.pos, p).normalize()
		const f = 5 * smoothstep(120, 0, d)
		this.pos.add(w.mult(f))
	}

	show(pointSize) {
		stroke(0)
		strokeWeight(this.size)
		point(this.pos.x, this.pos.y)
	}
}


// === Tab: Math ===
const smoothstep = (edge0, edge1, x) => {
	x = constrain((x - edge0) / (edge1 - edge0), 0, 1)
	return x * x * (3 - 2 * x)
}


